css:
@page {
	size: 50mm 25mm;
	margin: 0;
}

.print-format {
	page-width: 50mm;
	page-height: 25mm;
	margin-top: 0mm;
	margin-bottom: 0mm;
	margin-left: 0mm;
	margin-right: 0mm;
	padding: 0;
	width: 50mm;
	max-width: 50mm;
	min-height: 0;
}

.print-format .afm-albl {
	position: relative;
	box-sizing: border-box;
	width: 50mm;
	height: 25mm;
	overflow: hidden;
	direction: ltr;
	color: #171717;
	background-color: #FFFFFF;
	page-break-after: always;
	break-after: page;
}

.print-format .afm-albl-qr {
	position: absolute;
	top: 2mm;
	left: 2mm;
	width: 21mm;
	height: 21mm;
}

.print-format .afm-albl-side {
	position: absolute;
	top: 2mm;
	left: 24mm;
	width: 24mm;
	height: 21mm;
	overflow: hidden;
}

.print-format .afm-albl-logo {
	display: block;
	width: auto;
	max-width: 24mm;
	height: 5mm;
}

.print-format .afm-albl-name {
	margin-top: 1mm;
	max-height: 9.3mm;
	overflow: hidden;
	word-wrap: break-word;
	text-align: start;
	font-size: 6.5pt;
	line-height: 3.1mm;
	font-weight: bold;
}

.print-format .afm-albl-code {
	position: absolute;
	left: 0;
	bottom: 0;
	width: 24mm;
	height: 3mm;
	line-height: 3mm;
	white-space: nowrap;
	overflow: hidden;
	direction: ltr;
	font-family: "Courier New", Courier, monospace;
	font-size: 6pt;
	font-weight: bold;
}
